def determine_round_status(n, ratings):
    has_changed = False
    has_improved = False

    for i in range(1, n):
        prev_rating, curr_rating = ratings[i-1], ratings[i]

        if prev_rating != curr_rating:
            has_changed = True

        if prev_rating < curr_rating and prev_rating > ratings[i+1] if i + 1 < n else float('inf'):
            has_improved = True

    if has_changed and has_improved:
        return "rated"
    elif not has_changed and has_improved:
        return "unrated"
    else:
        return "maybe"

